hooks.command:
repo_root="$(git rev-parse --show-toplevel)" || { printf '{"continue":false,"stopReason":"Unable to locate the Git repository root"}
'; exit 1; }; if (cd "$repo_root" && bun run --silent fmt:fix >/dev/null); then printf '{"continue":true}
'; else status=$?; printf '{"continue":false,"stopReason":"bun run fmt:fix failed"}
'; exit "$status"; fi
